package com.rag.comment.support;

import org.springframework.test.context.DynamicPropertyRegistry;
import org.testcontainers.containers.PostgreSQLContainer;

import java.util.TimeZone;

/**
 * <p><b>测试用真 PostgreSQL（进程内单例容器）</b>。
 *
 * <h2>⚠️ 为什么必须跑真 PG（不能用 H2 顶替）</h2>
 * <p>comment 域的 8 个迁移脚本（{@code src/main/resources/db/migration/V1..V8}）里用到：
 * <ul>
 *   <li>{@code BIGINT GENERATED BY DEFAULT AS IDENTITY}（V1 subject / V4 comment_like /
 *       V5 report_record）
 *       ＋ <b>刻意不带</b> IDENTITY 的纯 {@code BIGINT} 主键（V2 comment_index ——
 *       主键由雪花 ID 自己赋值，让 PG 分配序列值会与雪花 ID 打架）；</li>
 *   <li>{@code TIMESTAMPTZ}（全部 7 张表的时间列 —— Go 的 {@code time.Time} 在
 *       gorm.io/driver/postgres 下建成 TIMESTAMPTZ，<b>不是</b> TIMESTAMP）
 *       ＋ {@code JSONB}（{@code comment_content.meta} /
 *       {@code comment_domain_fact_outbox.payload} / {@code .delivery_envelope}）；</li>
 *   <li>{@code ON CONFLICT DO NOTHING}（V4 的点赞锁锚 / V5 的举报记录）
 *       ＋ {@code ON CONFLICT (aggregate_id) DO UPDATE SET version = comment_fact_stream.version + 1
 *       RETURNING}（V7 的 {@code comment_fact_stream}）—— 后者必须<b>用表名限定</b>引用既有行值；</li>
 *   <li>{@code SELECT ... FOR UPDATE SKIP LOCKED LIMIT 1}（V8 的事实投递抢占）；</li>
 *   <li>{@code plpgsql} 触发器函数（V8 维护 {@code technical_received_at} / {@code delivered_at}）。</li>
 * </ul>
 * ⇒ H2 一个都不认（{@code ON CONFLICT} 的语法更是完全不同）
 * ⇒ ⇒ H2 上「跑绿」只能证明字符串被解析了，<b>不能证明 DDL 真的建对了</b> ⇒ <b>假绿</b>。
 * <p>⇒ 本类用 Testcontainers 起真 {@code postgres:16-alpine}。
 *
 * <h2>为什么是「单例」而不是每个测试类一个容器</h2>
 * <p>本域有多个 {@code @SpringBootTest} 上下文 ⇒ 每个类各起一个容器 ⇒ 慢 3 倍且机器上同时跑 3 个 PG。
 * ⇒ ⇒ 单例：<b>整个 JVM 起一次</b>，各测试类共用同一个库。
 * <p>⚠️ <b>共用库 ⇒ 数据必须互不冲突</b> ⇒ 各测试类用<b>唯一 uid</b>（带类名前缀的序号段），
 * 且断言前<b>先按 uid 清理</b>（本类不代劳，见 {@link #jdbcUrl()} 的用法说明）。
 *
 * <h2>🔴 会话时区：为什么本类把 JVM 默认时区钉成 {@code Asia/Shanghai}</h2>
 * <p>comment 域的 {@code application.yml:26-32} 明确要求连接串带 {@code ?TimeZone=Asia/Shanghai}
 * （{@code created_at} 是 TIMESTAMPTZ，wire 上要渲染成墙钟时间 ⇒ 会话时区差一个时区，
 * 渲染出来就差 8 小时）。
 * <p>⚠️ <b>实测（2026-11-04 · pgjdbc 42.7.10）：URL 里的 {@code TimeZone=} 参数<b>不生效</b></b> ——
 * 以 {@code -Duser.timezone=UTC} 起 JVM 并把 URL 写成
 * {@code jdbc:postgresql://…/first_db?TimeZone=Asia/Shanghai} ⇒ {@code SHOW timezone} 仍返回
 * {@code UTC} ⇒ ⇒ <b>pgjdbc 发给服务端的是「客户端 JVM 的默认时区」，URL 参数被忽略</b>
 * （{@code org.postgresql.PGProperty} 里<b>没有</b> {@code TIME_ZONE} 这一项）。
 * <p>⇒ ⇒ 想让<b>测试会话时区 == 生产会话时区</b>，唯一可靠的手段是<b>把 JVM 默认时区钉住</b>
 * ⇒ ⇒ 本类在 static 块里做这件事（发生在任何 JDBC 连接建立之前）。
 * <p>⚠️ 注入的 JDBC URL 里<b>仍然带上</b> {@code TimeZone=Asia/Shanghai}：一是让测试 URL 与
 * 生产 URL <b>同形</b>（可直接对照），二是万一将来 pgjdbc 支持了这个参数，测试侧已经就位。
 * <p>📌 <b>这条同时是一条给主 yml owner 的提示</b>：{@code ?TimeZone=Asia/Shanghai} 在 Java 侧
 * 目前是<b>无效参数</b> ⇒ 生产真正生效的会话时区 = <b>JVM 默认时区</b>（由部署时的
 * {@code -Duser.timezone} / 容器 TZ 决定）⇒ 生产容器若不是 Asia/Shanghai，渲染出来就会差一个时区。
 *
 * <p>📌 <b>禁止 {@code @EnabledIfDockerAvailable}</b>（AGENTS.md §五.8 守门硬规则 ③）
 * ⇒ ⇒ 容器不可用时**直接失败**（static 块抛异常 ⇒ {@code ExceptionInInitializerError}），
 * 而不是静默跳过（跳过 = 假绿）。
 *
 * <h3>L4 差异（AGENTS.md §3.2 三段式）</h3>
 * <ol>
 *   <li><b>比参照实现（like 域同款）多做了什么</b>：
 *       <ul>
 *         <li>注入的 JDBC URL <b>追加</b> {@code TimeZone=Asia/Shanghai}（like 域不需要 ——
 *             like 的 {@code application.yml:27-31} 明确<b>不加</b>该参数，理由是「会改会话时区 ⇒ 属行为变更」，
 *             而 comment 域<b>要</b>它 ⇒ <b>两域必须不同</b>，不可跨域统一）；</li>
 *         <li>static 块里<b>把 JVM 默认时区钉成 Asia/Shanghai</b>（like 域无此步）——
 *             理由见上（pgjdbc 实测：URL 参数无效，只有 JVM 默认时区说了算）。</li>
 *       </ul></li>
 *   <li><b>语义还一样吗</b>：一样 —— 容器镜像 / 库名 / 账号 / 单例语义 / 注入的三个键
 *       <b>全部与 like 域一致</b>；新增的只是「会话时区」这一项，它的作用是让测试环境
 *       <b>与本域生产环境对齐</b>（本域生产明确要求 Asia/Shanghai），不是引入新语义。</li>
 *   <li><b>B 出处</b>：真 PG 的必要性来自本域 8 个迁移脚本
 *       （{@code service/comment/src/main/resources/db/migration/V1..V8}）；
 *       账号 / 库名来自 B 侧 {@code docker-compose.yaml:140-147}
 *       （{@code POSTGRES_USER=admin} / {@code POSTGRES_DB=first_db}）；
 *       时区要求来自 B 侧 {@code comment-rpc/…/application.yml:45-49} 的必配说明
 *       （由 C 侧 {@code service/comment/src/main/resources/application.yml:26-32} 承接）。</li>
 * </ol>
 */
public final class TestPostgres {

    /**
     * 会话时区 —— 与本域 {@code application.yml:32} 的 URL 参数、以及 B 侧
     * {@code comment-rpc/…/application.yml:45-49} 的必配说明一致。
     */
    private static final String SESSION_TIME_ZONE = "Asia/Shanghai";

    private static final PostgreSQLContainer<?> PG = new PostgreSQLContainer<>("postgres:16-alpine")
            .withDatabaseName("first_db")
            .withUsername("admin")
            .withPassword("password");

    static {
        // ⚠️ 必须发生在**任何** JDBC 连接建立之前 —— pgjdbc 用「JVM 默认时区」当会话 TimeZone。
        TimeZone.setDefault(TimeZone.getTimeZone(SESSION_TIME_ZONE));
        PG.start();
    }

    private TestPostgres() {
    }

    /**
     * 把容器连接信息注入 Spring 的 {@code spring.datasource.*}。
     *
     * <p>⚠️ 本仓主 {@code application.yml} 里 {@code spring.datasource.password: ${POSTGRES_PASSWORD}}
     * <b>没有默认值</b>（fail-closed 纪律）⇒ 必须由外部注入，否则占位符解析失败。
     * ⇒ 本方法注入的 {@code spring.datasource.*} 三个键<b>优先级高于</b>主 yml
     * ⇒ ⇒ 主 yml 那条 {@code ${POSTGRES_PASSWORD}} 根本不会被解析到（也就不会因缺变量而炸）。
     */
    public static void register(DynamicPropertyRegistry registry) {
        registry.add("spring.datasource.url", TestPostgres::jdbcUrl);
        registry.add("spring.datasource.username", PG::getUsername);
        registry.add("spring.datasource.password", PG::getPassword);
    }

    /**
     * 容器的 JDBC URL —— 供测试里直接用 {@code JdbcTemplate} 查证据。
     *
     * <p>⚠️ <b>必须用本方法、不要自己拼 URL</b>：拼出来的串少了 {@code TimeZone=Asia/Shanghai}
     * ⇒ 与应用连接的会话时区可能不一致 ⇒ 取证时读出的墙钟时间与应用读出的对不上。
     */
    public static String jdbcUrl() {
        String base = PG.getJdbcUrl();
        // ⚠️ Testcontainers 1.21 的 getJdbcUrl() 自带 "?loggerLevel=OFF" ⇒ 这里必须用 "&" 续接。
        return base + (base.contains("?") ? "&" : "?") + "TimeZone=" + SESSION_TIME_ZONE;
    }

    public static String username() {
        return PG.getUsername();
    }

    public static String password() {
        return PG.getPassword();
    }
}
